SELECT b.auction_id AS auctionId, b.bid_price AS bidPrice, b.bid_time AS bidTime, b.user_id AS userId, u.user_name AS userName, (SELECT COUNT(*) FROM bids WHERE auction_id = #{auctionId}) AS totalBids FROM bids b INNER JOIN users u ON b.user_id = u.id
